css:
.sb-annual h3 {
	font-size: 9.5pt;
	font-weight: 600;
	margin: 4mm 0 1.5mm;
}

.sb-annual table.sb-bilanz {
	font-size: 8pt;
}

.sb-annual .sb-lines .sb-account {
	text-align: left;
}

.sb-annual table.sb-bilanz th.sb-num,
.sb-annual table.sb-bilanz td.sb-num {
	width: 21mm;
}

.sb-annual .sb-lines td.sb-level-2 {
	padding-left: 3mm;
}

.sb-annual .sb-lines td.sb-level-3 {
	padding-left: 6mm;
}

.sb-annual .sb-lines td.sb-level-4 {
	padding-left: 9mm;
}

.sb-annual .sb-lines td.sb-vermerk {
	color: #444;
	font-style: italic;
	padding-left: 3mm;
}

.sb-annual .sb-angabe {
	break-inside: avoid;
	page-break-inside: avoid;
	margin: 0 0 3mm;
}

.sb-annual .sb-angabe-label {
	font-weight: 600;
	margin: 0 0 0.8mm;
}

.sb-annual .sb-angabe-text {
	margin: 0 0 0.8mm;
	white-space: pre-line;
}

.sb-annual .sb-signature {
	margin: 0 0 1.5mm;
}

.sb-annual .sb-steps {
	margin: 0 0 3mm;
	padding-left: 5mm;
}

.sb-annual .sb-source,
.sb-annual .sb-unverified {
	color: #555;
	font-size: 8pt;
	margin: 0.5mm 0 1.5mm;
}

.sb-annual .sb-unverified {
	font-weight: 600;
}

.sb-annual .sb-notice {
	border: 0.3mm solid #888;
	margin: 0 0 4mm;
	padding: 2mm;
}
